const body = $('Webhook-PostMortem').item.json.body;
const customerName = body.customer_name || 'Ness';
const hostName = body.host_name || 'N/A';
const summary = body.summary || 'Sem resumo.';
const rootCause = body.root_cause || 'Sem causa raiz.';
const actions = (body.corrective_actions || []).join('\n- ');
const blast = (body.blast_radius || []).join(', ');
const fingerprint = body.incident_fingerprint || 'N/A';

const emailSubject = `Re: [NOC-ALERT] ${customerName} | Host: ${hostName} | Fingerprint: ${fingerprint}`;
const emailHtml = `<p><strong>📝 ANÁLISE DE CAUSA RAIZ (RCA) NOC 📝</strong></p>\n<p><strong>Cliente:</strong> ${customerName}</p>\n<p><strong>Equipamento:</strong> ${hostName}</p>\n<hr/>\n<p><strong>Resumo:</strong> ${summary}</p>\n<p><strong>Causa Raiz:</strong> ${rootCause}</p>\n<p><strong>Ações Corretivas:</strong><br/>- ${actions.replace(/\n/g, '<br/>- ')}</p>\n<p><strong>Raio de Impacto:</strong> ${blast}</p>\n<hr/>\n<p><small>Fingerprint: ${fingerprint}</small></p>`;

const whatsappText = `📝 *ANÁLISE DE CAUSA RAIZ (RCA) NOC* 📝\n\n*Cliente:* ${customerName}\n*Equipamento:* ${hostName}\n*Resumo:* ${summary}\n*Causa Raiz:* ${rootCause}\n\n*Ações Corretivas*:\n- ${actions}\n\n*Raio de Impacto:* ${blast}`;

return {
  "number": $env.NINF_WHATSAPP_NOC_GROUP_ID || 'group-id',
  "options": {
    "delay": 1200,
    "presence": "composing"
  },
  "text": whatsappText,
  "emailSubject": emailSubject,
  "emailHtml": emailHtml
};
